using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum TreatyOperation { Terminate,TerminationReceipt,RequestDefense,RequestSupply,Acknowledge,Decline,Resend }
public sealed record TreatyOperationInput(EntityId Id,TreatyOperation Action,EntityId Acceptance,EntityId Owner,EntityId Target,EntityId? Original=null,long EffectiveAt=0,long ReplyBy=0,long Amount=0,string? Evidence=null);
public sealed record TreatyOperationPaper(TreatyOperationInput Input,TreatyOperationInput Intent,TreatyOperation Kind,TreatyTerms Terms,EntityId Author,EntityId Recipient,EntityId Address,long At,long Revision,FactionStanceAuthority? Authority,EntityId Root,EntityId? CopyOf,long? ObservedAt,bool LegalService,string Message);
public sealed record TreatyOperationArrival(EntityId Paper,long At,long Revision,bool LegalService);
public sealed record TreatyOperationCard(EntityId Id,string Status,TreatyOperation Kind,long? ObservedAt,bool CanAcknowledge,bool CanDecline,bool CanResend);
