    public const string OperationKind="treaty-clause-operation";
    static TreatyOperationPaper[] Operations(ContractWorld w,long? at=null,long? rev=null)=>State(w).Operations.Where(p=>Before(p.At,p.Revision,at??w.ElapsedSeconds,rev??w.CommitSequence)).ToArray();
    static bool OperationOpened(ContractWorld w,TreatyOperationPaper p,EntityId who,long at,long rev)=>State(w).OperationOpenings.Any(o=>o.Message==p.Message&&o.Actor==who&&Before(o.At,o.Revision,at,rev));
    static bool OperationFailed(ContractWorld w,TreatyOperationPaper p,EntityId who,long at,long rev)=>State(w).FailureOpenings.Any(o=>o.Actor==who&&Before(o.At,o.Revision,at,rev)&&w.Messaging.Messages.Any(m=>m.Id==o.Message&&m.Kind=="delivery-failure"&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Message)));
    static TreatyOperationPaper OperationRoot(ContractWorld w,TreatyOperationPaper p)=>State(w).Operations.Single(q=>q.Input.Id==p.Root&&q.CopyOf==null);
    public static long? TruthEnd(ContractWorld w,EntityId acceptance,long? at=null,long? revision=null){long t=at??w.ElapsedSeconds,r=revision??w.CommitSequence;return Operations(w,t,r).Where(p=>p.Kind==TreatyOperation.Terminate&&p.Input.Acceptance==acceptance).SelectMany(p=>State(w).OperationArrivals.Where(a=>a.Paper==p.Input.Id&&a.LegalService&&Before(a.At,a.Revision,t,r)).Select(a=>Math.Max(a.At,p.Intent.EffectiveAt))).Where(end=>end<=t).Order().Select(end=>(long?)end).FirstOrDefault();}
    static bool KnowsEnding(ContractWorld w,EntityId actor,EntityId acceptance,long at,long rev)=>Operations(w,at,rev).Any(p=>p.Input.Acceptance==acceptance&&(p.Kind==TreatyOperation.Terminate&&p.Recipient==actor&&OperationOpened(w,p,actor,at,rev)&&State(w).OperationArrivals.Any(a=>a.Paper==p.Input.Id&&a.LegalService&&Before(a.At,a.Revision,at,rev))&&p.Intent.EffectiveAt<=at||p.Kind==TreatyOperation.TerminationReceipt&&p.Recipient==actor&&p.LegalService&&OperationOpened(w,p,actor,at,rev)&&OperationRoot(w,State(w).Operations.Single(q=>q.Input.Id==p.Input.Original)).Intent.EffectiveAt<=at));
    public static bool ClauseUsable(ContractWorld w,EntityId actor,EntityId acceptance,TreatyClause clause,long? at=null,long? revision=null){long t=at??w.ElapsedSeconds,r=revision??w.CommitSequence;return clause!=TreatyClause.None&&((int)clause&~15)==0&&Known(w,actor,t,r).Any(f=>f.Acceptance==acceptance&&(f.Terms.Clauses&clause)==clause&&Math.Max(f.Terms.From,f.At)<=t&&t<f.Terms.Until)&&!KnowsEnding(w,actor,acceptance,t,r);}
    static TreatyOperationPaper PrepareOperation(ContractWorld w,TreatyOperationInput i,EntityId actor,long at,long rev){long before=rev-1;Need(Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action),"条約履行の入力が不正です");var ps=Operations(w,at,before);
        if(i.Action==TreatyOperation.Resend){var old=ps.Single(p=>p.Input.Id==i.Original);Need(old.Author==actor&&OperationFailed(w,old,actor,at,before)&&i.Acceptance==old.Input.Acceptance&&i.Owner==old.Input.Owner&&i.Target==old.Input.Target&&i.EffectiveAt==0&&i.ReplyBy==0&&i.Amount==0&&i.Evidence==null,"本人が開封した不達の同じ原本だけ再送できます");Need(ps.Count(p=>p.Root==old.Root)<3,"同じ条約原本の写しは三通までです");return old with{Input=i,At=at,Revision=rev,CopyOf=old.Input.Id,Message="message:treaty-operation/"+Hash(i.Id.Value)};}
