        if(i.Action is TreatyOperation.Terminate or TreatyOperation.RequestDefense or TreatyOperation.RequestSupply){Need(Known(w,actor,at,before).Any(k=>k.Acceptance==i.Acceptance)&&at<f.Terms.Until&&!KnowsEnding(w,actor,i.Acceptance,at,before),"本人が知る有効な成立原本が必要です");Need(i.Original==null,"新しい行為に旧返答を混在できません");if(i.Action==TreatyOperation.Terminate){Need(i.EffectiveAt>=at+f.Terms.NoticeSeconds&&i.EffectiveAt<f.Terms.Until&&i.ReplyBy==0&&i.Amount==0&&i.Evidence==null,"条約に定めた解除予告期間を守ってください");Need(!ps.Any(p=>p.Kind==TreatyOperation.Terminate&&p.Input.Acceptance==i.Acceptance&&p.Author==actor),"同じ解除意思を重複発送できません");}
