        else{Need(i.Action is TreatyOperation.TerminationReceipt or TreatyOperation.Acknowledge or TreatyOperation.Decline,"この条約返答は扱えません");var source=ps.Single(p=>p.Input.Id==i.Original);Need(source.Input.Acceptance==i.Acceptance&&source.Recipient==actor&&source.Input.Owner==i.Target&&source.Input.Target==i.Owner&&OperationOpened(w,source,actor,at,before),"本人開封した要請・通知への返答が必要です");Need(!ps.Any(p=>p.CopyOf==null&&p.Input.Original is {} orig&&ps.Any(q=>q.Input.Id==orig&&q.Root==source.Root)&&p.Author==actor),"この原本へは返答済みです");Need(i.Amount==0&&i.EffectiveAt==0&&i.ReplyBy==0&&i.Evidence==null,"受領返答で条件を変えません");if(i.Action==TreatyOperation.TerminationReceipt)Need(source.Kind==TreatyOperation.Terminate,"解除通知ではありません");else Need(source.Kind is TreatyOperation.RequestDefense or TreatyOperation.RequestSupply&&at<=source.Intent.ReplyBy,"期限内の援軍・補給要請ではありません");recipient=source.Author;address=source.Authority!.Home;var arrival=State(w).OperationArrivals.Single(a=>a.Paper==source.Input.Id);observed=arrival.At;legal=arrival.LegalService;}
