    static MessageEnvelope OperationEnvelope(TreatyOperationPaper p)=>new(p.Message,p.Input.Acceptance.Value,OperationKind,p.Author.Value,p.Recipient.Value,System.Text.Encoding.UTF8.GetString(ContractJson.Write(p)),p.Address.Value,p.At);
    internal static void DispatchOperation(ContractWorld w,TreatyOperationInput i,EntityId actor){var p=PrepareOperation(w,i,actor,w.ElapsedSeconds,w.CommitSequence);w.Treaties=State(w) with{Operations=[..State(w).Operations,p]};MessageFlow.Send(w.Messaging,OperationEnvelope(p),p.At,1);w.SealedMessages=[..w.SealedMessages,new(p.Message)];}
    public static string? OperationAddress(ContractWorld w,MessageEnvelope m)=>Operations(w).SingleOrDefault(p=>p.Message==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
    internal static void RecordOperationOpening(ContractWorld w,EntityId actor,string id){if(w.Treaties==null)return;var p=State(w).Operations.SingleOrDefault(p=>p.Message==id&&p.Recipient==actor);if(p!=null){if(State(w).OperationOpenings.Any(o=>o.Message==id))return;Need(MessageFlow.Knows(w.Messaging,id,actor.Value),"本人の開封ではありません");w.Treaties=State(w) with{OperationOpenings=[..State(w).OperationOpenings,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]};}else if(!State(w).FailureOpenings.Any(o=>o.Message==id)&&w.Messaging.Messages.Any(m=>m.Id==id&&m.Kind=="delivery-failure"&&m.RecipientId==actor.Value&&State(w).Operations.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Message))))w.Treaties=State(w) with{FailureOpenings=[..State(w).FailureOpenings,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]};}
    static void UpdateOperations(ContractWorld w){if(w.Treaties==null)return;foreach(var p in State(w).Operations){var arrived=w.Messaging.Attempts.Where(a=>a.MessageId==p.Message&&a.ReceiverId==p.Recipient.Value&&a.Status==AttemptStatus.Delivered).OrderBy(a=>a.FinishedAt).FirstOrDefault();if(arrived?.FinishedAt is not {} at)continue;if(!State(w).OperationArrivals.Any(a=>a.Paper==p.Input.Id)){bool legal=FactionStances.ResolveAuthority(w,p.Recipient,p.Input.Target,at,w.CommitSequence)!=null;w.Treaties=State(w) with{OperationArrivals=[..State(w).OperationArrivals,new(p.Input.Id,at,w.CommitSequence,legal)]};}if(p.Recipient!=w.PlayerControl){if(!MessageFlow.Knows(w.Messaging,p.Message,p.Recipient.Value))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(p.Message,p.Recipient.Value,w.ElapsedSeconds,p.Message)];RecordOperationOpening(w,p.Recipient,p.Message);}}
        foreach(var m in w.Messaging.Messages.Where(m=>m.Kind=="delivery-failure"&&State(w).Operations.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Message))).ToArray()){if(!w.SealedMessages.Contains(new(m.Id)))w.SealedMessages=[..w.SealedMessages,new(m.Id)];if(m.RecipientId!=w.PlayerControl.Value&&w.Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.Status==AttemptStatus.Delivered)){if(!MessageFlow.Knows(w.Messaging,m.Id,m.RecipientId))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(m.Id,m.RecipientId,w.ElapsedSeconds,m.Id)];RecordOperationOpening(w,new(m.RecipientId),m.Id);}}}
    static (TreatyOperationInput Input,EntityId Actor)? NextOperation(ContractWorld w){foreach(var p in Operations(w).Where(p=>p.Recipient!=w.PlayerControl&&p.Kind is TreatyOperation.Terminate or TreatyOperation.RequestDefense or TreatyOperation.RequestSupply)){if(!OperationOpened(w,p,p.Recipient,w.ElapsedSeconds,w.CommitSequence)||Operations(w).Any(q=>q.CopyOf==null&&q.Input.Original is {} orig&&Operations(w).Any(x=>x.Input.Id==orig&&x.Root==p.Root)&&q.Author==p.Recipient)||FactionStances.ResolveAuthority(w,p.Recipient,p.Input.Target,w.ElapsedSeconds,w.CommitSequence)==null)continue;if(p.Kind!=TreatyOperation.Terminate&&w.ElapsedSeconds>p.Intent.ReplyBy)continue;return(new(new("request:treaty-operation-receipt/"+Hash(p.Input.Id.Value)),p.Kind==TreatyOperation.Terminate?TreatyOperation.TerminationReceipt:TreatyOperation.Acknowledge,p.Input.Acceptance,p.Input.Target,p.Input.Owner,p.Input.Id),p.Recipient);}return null;}
    internal static void TakeOperationTurns(WorldSession session){for(int i=0;i<32;i++){var next=NextOperation(session.DiagnosticSnapshot());if(next==null)return;session.AutoTreatyOperation(next.Value.Input,next.Value.Actor);}}
    internal static void AutomaticOperation(ContractWorld w,TreatyOperationInput i,EntityId actor){var c=w.ForkTransportLocation();c.CommitSequence--;var next=NextOperation(c);Need(next is {}&&next.Value.Input==i&&next.Value.Actor==actor,"受領原本からの自動返答ではありません");DispatchOperation(w,i,actor);}
    public static bool CanOperate(ContractWorld w,TreatyOperationInput i,EntityId actor){try{PrepareOperation(w,i,actor,w.ElapsedSeconds,w.CommitSequence+1);return true;}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return false;}}
    public static TreatyOperationCard[] OperationView(ContractWorld w)=>Operations(w).Where(p=>p.Author==w.PlayerControl||OperationOpened(w,p,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence)).Select(p=>{bool received=OperationOpened(w,p,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence);var ack=Operations(w).FirstOrDefault(q=>q.Input.Original==p.Input.Id&&q.Recipient==w.PlayerControl&&OperationOpened(w,q,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence));string status=ack!=null?(ack.Kind==TreatyOperation.Decline?"辞退の返書を開封":"受領返書を開封・実行済みではない"):received?"本人開封・返答待ち":"発送・相手の状況は未確認";var common=new TreatyOperationInput(new("request:operation-preview"),TreatyOperation.Acknowledge,p.Input.Acceptance,p.Input.Target,p.Input.Owner,p.Input.Id);return new TreatyOperationCard(p.Input.Id,status,p.Kind,p.ObservedAt,CanOperate(w,common,w.PlayerControl),CanOperate(w,common with{Action=TreatyOperation.Decline},w.PlayerControl),CanOperate(w,new(new("request:operation-retry-preview"),TreatyOperation.Resend,p.Input.Acceptance,p.Input.Owner,p.Input.Target,p.Input.Id),w.PlayerControl));}).ToArray();
    static IEnumerable<(long At,long Revision)> OperationInputs(ContractWorld w)=>Operations(w).Select(p=>(p.At,p.Revision)).Concat(State(w).OperationOpenings.Where(o=>o.Actor==w.PlayerControl).Select(o=>(o.At,o.Revision))).Concat(State(w).FailureOpenings.Where(o=>o.Actor==w.PlayerControl).Select(o=>(o.At,o.Revision)));
    static IEnumerable<long> OperationChanges(ContractWorld w)=>Operations(w).SelectMany(p=>new[]{p.At,p.Intent.EffectiveAt,p.Intent.ReplyBy+1}).Concat(State(w).OperationArrivals.Select(a=>a.At));
    static void RewindOperations(ContractWorld w,long at,long rev){if(w.Treaties is {} s)w.Treaties=s with{Operations=s.Operations.Where(p=>Before(p.At,p.Revision,at,rev)).ToArray(),OperationOpenings=s.OperationOpenings.Where(o=>Before(o.At,o.Revision,at,rev)).ToArray(),FailureOpenings=s.FailureOpenings.Where(o=>Before(o.At,o.Revision,at,rev)).ToArray(),OperationArrivals=s.OperationArrivals.Where(a=>Before(a.At,a.Revision,at,rev)).ToArray()};}
    static void ValidateOperations(ContractWorld w){var s=State(w);Need(s.Operations!=null&&s.OperationOpenings!=null&&s.FailureOpenings!=null&&s.OperationArrivals!=null&&s.Operations.Select(p=>p.Input.Id).Distinct().Count()==s.Operations.Length&&s.OperationOpenings.Select(o=>o.Message).Distinct().Count()==s.OperationOpenings.Length&&s.OperationArrivals.Select(a=>a.Paper).Distinct().Count()==s.OperationArrivals.Length,"条約の履行原本・開封・到達が不正です");foreach(var p in s.Operations){Need(p.At<=w.ElapsedSeconds&&p.Revision>0&&p.Revision<=w.CommitSequence&&!FactionStances.OtherIdUsed(w,p.Input.Id,includeTreaties:false)&&!FactionStances.OwnIdUsed(w,p.Input.Id)&&!s.Papers.Any(q=>q.Input.Id==p.Input.Id),"条約履行のID・時点が不正です");Need(p==PrepareOperation(w,p.Input,p.Author,p.At,p.Revision)&&w.Messaging.Messages.Contains(OperationEnvelope(p))&&w.SealedMessages.Contains(new(p.Message)),"条項・署名・宛先・返答原本が一致しません");foreach(var c in w.Couriers!.Missions.Where(c=>w.Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==p.Message)))Need(c.Destination==NewGameWorld.Node(p.Address.Value),"現在地追尾にすり替えています");Need(MessageFlow.Knows(w.Messaging,p.Message,p.Recipient.Value)==s.OperationOpenings.Any(o=>o.Message==p.Message),"未開封の条約履行原本を知っています");}
