public sealed partial class WorldSession
{
    internal void AutoTreatyOperation(TreatyOperationInput i,EntityId actor){lock(gate)Change(w=>TreatyNegotiations.AutomaticOperation(w,i,actor));}
    public CommandResult OperateTreaty(TreatyOperationInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl)return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"本人の条約操作ではありません");var old=state.Treaties?.Operations.SingleOrDefault(p=>p.Input.Id==i.Id);if(old!=null)return new(old.Input==i&&old.Author==actor?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"発送済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の原本です");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>TreatyNegotiations.DispatchOperation(w,i,actor));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"条約の通知・要請を書状で発送しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
